mapper.select:

where 1 = 1

    and p.project_id = #{projectId}


    and p.project_name like concat('%', #{projectName}, '%')


    and p.provider = #{provider}


    and p.business_system_id = #{businessSystemId}


    and p.dept_id = #{deptId}


    and p.owner_user_id = #{ownerUserId}


    and p.status = #{status}


    and p.last_check_status = #{lastCheckStatus}


    and (p.owner_user_id = #{accessUserId} or find_in_set(#{accessUserId}, bs.manager_ids))

${params.dataScope}
order by p.project_id desc

select count(1)
from review_project p
inner join sys_business_system bs on bs.system_id = p.business_system_id
inner join sys_dept d on d.dept_id = p.dept_id
inner join sys_user owner on owner.user_id = p.owner_user_id
inner join review_git_credential c on c.credential_id = p.credential_id
where 1 = 1

    and p.project_id = #{projectId}


    and p.project_name like concat('%', #{projectName}, '%')


    and p.provider = #{provider}


    and p.business_system_id = #{businessSystemId}


    and p.dept_id = #{deptId}


    and p.owner_user_id = #{ownerUserId}


    and p.status = #{status}


    and p.last_check_status = #{lastCheckStatus}


    and (p.owner_user_id = #{accessUserId} or find_in_set(#{accessUserId}, bs.manager_ids))

${params.dataScope}

select project_id, project_name, provider, repository_owner, repository_name, repository_full_path,
       status, pr_review_enabled, pr_target_branches, push_review_enabled, push_trigger_branches,
       webhook_secret_ciphertext, credential_id,
       model_id, primary_stack, template_id, review_mode, engine_code,
       scope_exclude_patterns, scope_include_tests, scope_report_existing, scope_expand_enabled,
       notify_enabled, notify_channel_id, notify_on_failure
from review_project
where provider = #{provider}
  and repository_owner = #{repositoryOwner}
  and repository_name = #{repositoryName}

  and project_id != #{excludeProjectId}

limit 1

select project_id, project_name, provider, repository_owner, repository_name, repository_full_path, status, pr_review_enabled, pr_target_branches, push_review_enabled, push_trigger_branches, webhook_secret_ciphertext, credential_id, model_id, primary_stack, template_id, review_mode, engine_code, scope_exclude_patterns, scope_include_tests, scope_report_existing, scope_expand_enabled, notify_enabled, notify_channel_id, notify_on_failure from review_project where provider = #{provider} and repository_full_path = #{repositoryFullPath}
and project_id != #{excludeProjectId}
limit 1

mapper.update:
update review_project
set last_webhook_time = sysdate(),
    last_webhook_result = #{lastWebhookResult}
where project_id = #{projectId}

update review_project
set status = #{status}, update_by = #{updateBy}, update_time = sysdate()
where project_id = #{projectId}
